import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { addToCart } from '../services/api';
import { isAuthenticated } from '../util/auth';

const ProductCard = ({ product, onCartUpdate, index = 0 }) => {
  const [loading, setLoading] = useState(false);
  const [quantity, setQuantity] = useState(1);
  const [isHovered, setIsHovered] = useState(false);

  const handleAddToCart = async () => {
    if (!isAuthenticated()) {
      alert('Please login to add items to cart');
      return;
    }

    try {
      setLoading(true);
      await addToCart(product._id, quantity);
      if (onCartUpdate) {
        onCartUpdate();
      }
      alert('Product added to cart!');
    } catch (error) {
      alert(error.response?.data?.message || 'Error adding to cart');
    } finally {
      setLoading(false);
    }
  };

  const getCategoryClass = (category) => {
    const classes = {
      milk: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300',
      ghee: 'bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-300',
      cheese: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300',
      butter: 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-300',
      curd: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300',
      paneer: 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-300',
      cream: 'bg-pink-100 text-pink-800 dark:bg-pink-900/30 dark:text-pink-300',
      yogurt: 'bg-teal-100 text-teal-800 dark:bg-teal-900/30 dark:text-teal-300',
      lassi: 'bg-cyan-100 text-cyan-800 dark:bg-cyan-900/30 dark:text-cyan-300',
      buttermilk: 'bg-lime-100 text-lime-800 dark:bg-lime-900/30 dark:text-lime-300'
    };
    return classes[category] || 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300';
  };

  // Animation delay based on index for staggered entrance
  const animationDelay = `${index * 0.1}s`;

  return (
    <div 
      className="card group relative overflow-hidden transition-all duration-300 hover:shadow-lg hover:shadow-primary-500/10"
      style={{ animationDelay }}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      {/* Product Image with zoom effect */}
      <div className="h-48 bg-gray-100 dark:bg-gray-700 flex items-center justify-center overflow-hidden relative">
        <div className={`absolute inset-0 bg-gradient-to-tr from-transparent to-black/10 opacity-0 group-hover:opacity-100 transition-opacity duration-300 z-10`} />
        {product.image ? (
          <img 
            src={product.image} 
            alt={product.name}
            className={`w-full h-full object-cover transition-transform duration-500 ${isHovered ? 'scale-110' : 'scale-100'}`}
          />
        ) : (
          <div className="w-24 h-24 bg-primary-200 dark:bg-primary-800 rounded-full flex items-center justify-center">
            <span className="text-4xl">🥛</span>
          </div>
        )}
      </div>

      {/* Product Info */}
      <div className="p-4">
        {/* Category Badge */}
        <span className={`inline-block px-2 py-1 text-xs font-medium rounded-full mb-2 ${getCategoryClass(product.category)}`}>
          {product.category}
        </span>

        {/* Product Name */}
        <h3 className="text-lg font-semibold text-gray-800 dark:text-gray-50 mb-1 group-hover:text-primary-600 dark:group-hover:text-primary-400 transition-colors">
          {product.name}
        </h3>

        {/* Description */}
        <p className="text-sm text-gray-600 dark:text-gray-400 mb-2 line-clamp-2">
          {product.description}
        </p>

        {/* Price and Unit */}
        <div className="flex items-center justify-between mb-3">
          <div>
            <span className="text-xl font-bold text-primary-600 dark:text-primary-400">₹{product.price}</span>
            <span className="text-sm text-gray-500 dark:text-gray-400">/{product.unit}</span>
          </div>
          <div className="text-sm text-gray-500 dark:text-gray-400">
            Stock: {product.stock}
          </div>
        </div>

        {/* Quantity Selector and Add to Cart */}
        <div className="flex items-center space-x-2">
          <div className="flex items-center border border-gray-300 dark:border-gray-600 rounded-lg">
            <button
              onClick={() => setQuantity(Math.max(1, quantity - 1))}
              className="w-8 h-8 flex items-center justify-center text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
            >
              -
            </button>
            <span className="w-8 text-center text-gray-800 dark:text-gray-200">{quantity}</span>
            <button
              onClick={() => setQuantity(Math.min(product.stock, quantity + 1))}
              className="w-8 h-8 flex items-center justify-center text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
            >
              +
            </button>
          </div>
          <button
            onClick={handleAddToCart}
            disabled={loading || product.stock === 0}
            className="flex-1 btn btn-primary disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-300 hover:scale-[1.02] active:scale-[0.98]"
          >
            {loading ? 'Adding...' : product.stock === 0 ? 'Out of Stock' : 'Add to Cart'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ProductCard;
